Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -17,4 +17,29 @@
 <div class="overlay" id="intro"><section class="card"><div class="hero-hedgehog">🦔</div><div class="eyebrow">Большое лесное приключение</div><h1>Ёж и яблочный лес</h1><p>Проберись сквозь лес, одолей деревянных стражей и собери все <b>50 яблок</b>. Каждое найденное яблоко становится чуть больше!</p><div class="keyline"><span class="key">J · УДАР НОСОМ</span><span class="key">K · ИГЛА</span><span class="key">L · ШАР НА 20 СЕК</span></div><p>Жёлудь временно увеличит запас здоровья до 8 сердец. Берегись стражей — у тебя всего пять сердец.</p><button class="start" id="startBtn">В лес! →</button></section></div>
 <div class="overlay hidden" id="end"><section class="card"><div class="hero-hedgehog" id="endIcon">🍎</div><div class="eyebrow" id="endEyebrow">Приключение окончено</div><h1 id="endTitle">Лес победил</h1><p id="endText"></p><button class="start" id="restartBtn">Начать сначала ↻</button></section></div>
 </main>
 <script>
+(()=>{
+const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
+const ui={count:document.querySelector('#appleCount'),hearts:document.querySelector('#hearts'),buff:document.querySelector('#buffStatus'),intro:document.querySelector('#intro'),end:document.querySelector('#end')};
+const W=4400,H=3400,TAU=Math.PI*2;let vw=0,vh=0,dpr=1,camera={x:0,y:0},last=0,running=false,won=false,keys={},mouseAim={x:1,y:0},shake=0;
+let player,apples=[],enemies=[],needles=[],cones=[],acorns=[],trees=[],shrubs=[],particles=[],collected=0,elapsed=0;
+const rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function resize(){dpr=Math.min(devicePixelRatio||1,2);vw=innerWidth;vh=innerHeight;canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);canvas.style.width=vw+'px';canvas.style.height=vh+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
+const colors=['#dd5b3e','#d99a3f','#8a61b2','#e1b34d'];
+function seedForest(){trees=[];shrubs=[];for(let i=0;i<320;i++)trees.push({x:rand(40,W-40),y:rand(40,H-40),r:rand(22,57),tone:Math.floor(rand(0,4)),layer:Math.random()});for(let i=0;i<220;i++)shrubs.push({x:rand(30,W-30),y:rand(30,H-30),r:rand(8,19),tone:Math.random()})}
+function startGame(){
+collected=0;elapsed=0;won=false;running=true;needles=[];cones=[];particles=[];apples=[];enemies=[];acorns=[];
+player={x:W*.5,y:H*.5,r:18,speed:210,hp:5,maxHp:5,face:{x:1,y:0},invuln:0,attack:0,ball:0,ballCd:0,acorn:0,hooked:0};
+// Distribute apple groves over the full forest; each has two guardians.
+for(let i=0;i<50;i++){let a=i*2.399963,rad=210+Math.sqrt(i)*275;let x=clamp(W/2+Math.cos(a)*rad,150,W-150),y=clamp(H/2+Math.sin(a)*rad*.76,150,H-150);if(i===0){x=W/2+230;y=H/2-60}
+let apple={x,y,r:9+i*.42,index:i,got:false,bob:rand(0,TAU)};apples.push(apple);
+for(let k=0;k<2;k++){let ang=rand(0,TAU),d=rand(72,112);let types=['club','bow','sword','hook'];let type=types[(i*2+k+Math.floor(rand(0,4)))%types.length];enemies.push({x:x+Math.cos(ang)*d,y:y+Math.sin(ang)*d,r:17,type,hp:2,maxHp:2,face:{x:Math.cos(-ang),y:Math.sin(-ang)},awake:false,attack:rand(.4,1.8),hurt:0,stun:0,shoot:rand(1.3,2.7),wander:rand(0,TAU),hook:0,seed:i*7+k})}}
+for(let i=0;i<19;i++){let a=rand(0,TAU),d=rand(240,1500);acorns.push({x:clamp(W/2+Math.cos(a)*d,100,W-100),y:clamp(H/2+Math.sin(a)*d,100,H-100),r:12,got:false,bob:rand(0,TAU)})}
+ui.intro.classList.add('hidden');ui.end.classList.add('hidden');camera.x=player.x;camera.y=player.y;updateHud();last=performance.now();requestAnimationFrame(loop)}
+function updateHud(){ui.count.textContent=collected;ui.hearts.textContent='❤️'.repeat(player.maxHp)+'🖤'.repeat(Math.max(0,player.maxHp-player.hp));if(player.acorn>0){ui.buff.className='status acorn-on';ui.buff.textContent='🌰 ЗАПАС +'+Math.ceil(player.acorn)+'с'}else if(player.ball>0){ui.buff.className='status';ui.buff.textContent='✹ ШАР '+Math.ceil(player.ball)+'с'}else{ui.buff.className='status';ui.buff.textContent=player.ballCd>0?'✹ Откат '+Math.ceil(player.ballCd)+'с':'🌰 Найди желудь'}}
+function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
+function drawGround(){ctx.fillStyle='#648c52';ctx.fillRect(0,0,W,H);let tile=120;let sx=Math.floor(camera.x/vw*0); // keep texture anchored to world
+for(let y=Math.floor((camera.y-vh/2)/tile)*tile;y<camera.y+vh/2+tile;y+=tile)for(let x=Math.floor((camera.x-vw/2)/tile)*tile;x<camera.x+vw/2+tile;x+=tile){let n=(Math.sin(x*12.989+y*78.23)*43758.5453)%1;ctx.fillStyle=n>.05?'#668c50':'#62864d';ctx.fillRect(x,y,tile,tile);for(let j=0;j<3;j++){let dx=x+((j*43+((x/tile*17+y/tile*9)%31)+tile)%tile),dy=y+((j*71+(y/tile*23+x/tile*11)%47+tile)%tile);ctx.fillStyle='#a5af6650';ctx.beginPath();ctx.ellipse(dx,dy,2.5,1.5,.4,0,TAU);ctx.fill()}}
+// winding pale trail toward distant groves
+ctx.strokeStyle='#b8aa7044';ctx.lineWidth=44;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(W/2,H/2);for(let i=1;i<=9;i++){let a=i*2.4,r=210+Math.sqrt(i*5.5)*275;ctx.lineTo(clamp(W/2+Math.cos(a)*r,120,W-120),clamp(H/2+Math.sin(a)*r*.76,120,H-120))}ctx.stroke();
+ctx.strokeStyle='#385c3b';ctx.lineWidth=18;ctx.strokeRect(0,0,W,H);}

input.newString:
ctx.strokeStyle='#385c3b';ctx.lineWidth=18;ctx.strokeRect(0,0,W,H);}
function visible(o,pad=70){return o.x>camera.x-vw/2-pad&&o.x<camera.x+vw/2+pad&&o.y>camera.y-vh/2-pad&&o.y<camera.y+vh/2+pad}
function drawTrees(){for(const t of trees){if(!visible(t,t.r+12))continue;ctx.fillStyle='#254b36aa';ctx.beginPath();ctx.ellipse(t.x+6,t.y+8,t.r*.85,t.r*.68,0,0,TAU);ctx.fill();ctx.fillStyle=['#326344','#3d7048','#477b4c','#2e5a3d'][t.tone];ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,TAU);ctx.fill();ctx.fillStyle=['#518653','#5b9158','#63975c','#477b4c'][t.tone];ctx.beginPath();ctx.arc(t.x-t.r*.22,t.y-t.r*.28,t.r*.64,0,TAU);ctx.fill();ctx.fillStyle='#ffffff12';ctx.beginPath();ctx.arc(t.x-t.r*.34,t.y-t.r*.44,t.r*.24,0,TAU);ctx.fill();ctx.fillStyle='#775439';ctx.fillRect(t.x-3,t.y+t.r*.48,7,10)}for(const s of shrubs){if(!visible(s))continue;ctx.fillStyle=s.tone>.5?'#527a42':'#74914a';ctx.beginPath();ctx.ellipse(s.x,s.y,s.r,s.r*.62,-.3,0,TAU);ctx.fill();ctx.fillStyle='#9da85d';ctx.beginPath();ctx.arc(s.x-4,s.y-3,3,0,TAU);ctx.fill()}}
function drawApple(a){if(a.got||!visible(a,50))return;let bob=Math.sin(elapsed*2+a.bob)*3,r=a.r;ctx.fillStyle='#20372b55';ctx.beginPath();ctx.ellipse(a.x,a.y+12,r*.95,5,0,0,TAU);ctx.fill();ctx.fillStyle='#d74f36';ctx.beginPath();ctx.arc(a.x,a.y+bob,r,0,TAU);ctx.fill();ctx.beginPath();ctx.arc(a.x-r*.36,a.y+bob-r*.25,r*.56,0,TAU);ctx.fillStyle='#e96645';ctx.fill();ctx.strokeStyle='#75482e';ctx.lineWidth=Math.max(2,r*.18);ctx.beginPath();ctx.moveTo(a.x,a.y+bob-r*.8);ctx.lineTo(a.x+2,a.y+bob-r*1.14);ctx.stroke();ctx.fillStyle='#66a54e';ctx.beginPath();ctx.ellipse(a.x+6,a.y+bob-r*.93,r*.4,r*.2,-.4,0,TAU);ctx.fill();if(a.index%10===9){ctx.strokeStyle='#ffe18a88';ctx.lineWidth=2;ctx.beginPath();ctx.arc(a.x,a.y+bob,r+8+Math.sin(elapsed*3)*2,0,TAU);ctx.stroke()}}
function drawAcorn(a){if(a.got||!visible(a,40))return;let y=a.y+Math.sin(elapsed*3+a.bob)*3;ctx.fillStyle='#263c2b55';ctx.beginPath();ctx.ellipse(a.x,y+12,13,4,0,0,TAU);ctx.fill();ctx.fillStyle='#b97638';ctx.beginPath();ctx.ellipse(a.x,y,8,11,-.3,0,TAU);ctx.fill();ctx.fillStyle='#714a2e';ctx.beginPath();ctx.ellipse(a.x,y-5,10,5,0,0,TAU);ctx.fill();ctx.fillRect(a.x-2,y-11,4,4);ctx.fillStyle='#ffe18a';ctx.beginPath();ctx.arc(a.x-2,y-1,2,0,TAU);ctx.fill()}
function drawHedgehog(){let p=player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.atan2(p.face.y,p.face.x));ctx.fillStyle='#20372b55';ctx.beginPath();ctx.ellipse(0,16,22,8,0,0,TAU);ctx.fill();if(p.ball>0){ctx.fillStyle='#754c35';ctx.beginPath();ctx.arc(0,0,21,0,TAU);ctx.fill();for(let i=0;i<13;i++){let a=i*TAU/13;ctx.strokeStyle='#f0d7a4';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(Math.cos(a)*13,Math.sin(a)*13);ctx.lineTo(Math.cos(a)*26,Math.sin(a)*26);ctx.stroke()}ctx.fillStyle='#d69b58';ctx.beginPath();ctx.arc(3,2,8,0,TAU);ctx.fill()}else{ctx.fillStyle='#58402f';ctx.beginPath();for(let i=0;i<13;i++){let a=Math.PI*.62+i*Math.PI*.82/12;let r=i%2?21:28;let x=-4+Math.cos(a)*r,y=-5+Math.sin(a)*r; i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.lineTo(13,10);ctx.lineTo(-8,14);ctx.closePath();ctx.fill();ctx.fillStyle='#bd8251';ctx.beginPath();ctx.ellipse(0,3,18,14,0,0,TAU);ctx.fill();ctx.fillStyle='#e6b782';ctx.beginPath();ctx.ellipse(11,5,12,8,0,0,TAU);ctx.fill();ctx.fillStyle='#f3cfa0';ctx.beginPath();ctx.arc(6,-6,9,0,TAU);ctx.fill();ctx.fillStyle='#2d3025';ctx.beginPath();ctx.arc(8,-8,2,0,TAU);ctx.arc(22,4,3,0,TAU);ctx.fill();ctx.fillStyle='#926540';ctx.fillRect(-8,12,7,5);ctx.fillRect(7,12,7,5)}ctx.restore();if(p.invuln>0&&Math.floor(elapsed*14)%2===0){ctx.strokeStyle='#fff7bd';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,25,0,TAU);ctx.stroke()}}

